-- K-097: harga jual hanya ditentukan qty (syarat qty per tier, bisa per barang); "siapa pembelinya" pindah ke
-- promo lewat golongan pelanggan, pelanggan tertentu, dan syarat belanja kumulatif.
CREATE TABLE "golongan_pelanggan" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "golongan_pelanggan_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nama" varchar(60) NOT NULL,
	"keterangan" varchar(150),
	"status_aktif" varchar(10) DEFAULT 'AKTIF' NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "golongan_pelanggan_nama_key" UNIQUE("nama"),
	CONSTRAINT "chk_golongan_pelanggan_status" CHECK (status_aktif in ('AKTIF','NONAKTIF'))
);
--> statement-breakpoint
CREATE TABLE "promo_pelanggan" (
	"id_promo" bigint NOT NULL,
	"id_pelanggan" bigint NOT NULL,
	CONSTRAINT "promo_pelanggan_pkey" PRIMARY KEY("id_promo","id_pelanggan")
);
