-- Syarat qty lama ("saran") menjadi syarat qty tier otomatis.
UPDATE "tingkat_harga" SET "min_qty" = "saran_min_qty" WHERE "saran_min_qty" > 0 AND NOT "is_default";--> statement-breakpoint
-- Tier pelanggan (selain tier default) menjadi golongan pelanggan bernama sama.
INSERT INTO "golongan_pelanggan" ("nama")
SELECT DISTINCT t."nama" FROM "pelanggan" p
JOIN "tingkat_harga" t ON t."id" = p."id_tingkat_harga"
WHERE NOT t."is_default";--> statement-breakpoint
UPDATE "pelanggan" p SET "id_golongan" = g."id"
FROM "tingkat_harga" t, "golongan_pelanggan" g
WHERE t."id" = p."id_tingkat_harga" AND NOT t."is_default" AND g."nama" = t."nama";
